import type { Track } from '@/services/music/types'

/**
 * The playable catalogue.
 *
 * Every entry below describes the file it points at and nothing else. The
 * title, artist and duration belong to that recording, so what the interface
 * shows is always what comes out of the speakers.
 *
 * The audio shipped here is original instrumental music generated by
 * `tools/generate-demo-audio.py` and released under CC0, which is why the
 * catalogue can claim it outright. To add your own, see MUSIC_CATALOG.md —
 * drop an MP3 in `public/audio/` and add a record here.
 *
 * `duration` is kept honest by the generator: running it rewrites every
 * duration from the decoded length of the file.
 */

const LICENSE = 'CC0 1.0'
const LICENSE_URL = 'https://creativecommons.org/publicdomain/zero/1.0/'
const ATTRIBUTION = 'Original music generated for Sonder'
const ATTRIBUTION_URL = 'https://creativecommons.org/publicdomain/zero/1.0/'

/** Applied to every shipped track so a record only carries what is distinct. */
function local(
  track: Omit<Track, 'source' | 'sourceId' | 'license' | 'licenseUrl' | 'attribution' | 'attributionUrl'>,
): Track {
  return {
    ...track,
    source: 'local',
    sourceId: 'sonder-originals',
    license: LICENSE,
    licenseUrl: LICENSE_URL,
    attribution: `${ATTRIBUTION} · ${track.artist}`,
    attributionUrl: ATTRIBUTION_URL,
  }
}

